        absoluteY: 217,
        indirectX: 193,
        indirectY: 209,
        indirect: 210,
        indirectLong: 207,
        indirectLongY: 223,
        stackRelative: 195,
        stackRelativeIndirectY: 211,
        absoluteLong: 207,
        absoluteLongX: 223,
