      CLC: 24,
      CLD: 216,
      CLI: 88,
      CLV: 184,
      DEX: 202,
      DEY: 136,
      INX: 232,
      INY: 200,
      NOP: 234,
      PHA: 72,
      PHB: 139,
      PHD: 11,
      PHK: 75,
      PHP: 8,
      PHX: 218,
      PHY: 90,
      PLA: 104,
      PLB: 171,
      PLD: 43,
      PLP: 40,
      PLX: 250,
      PLY: 122,
      RTI: 64,
      RTL: 107,
      RTS: 96,
      SEC: 56,
      SED: 248,
      SEI: 120,
      STP: 219,
      TAX: 170,
      TAY: 168,
      TCD: 91,
      TCS: 27,
      TDC: 123,
      TSC: 59,
      TSX: 186,
      TXA: 138,
      TXS: 154,
      TXY: 155,
      TYA: 152,
      TYX: 187,
      WAI: 203,
      XBA: 235,
      XCE: 251
